-- 0095_library_templates_39_48_101_110.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Fixit" v1, generated from
-- packages/store-sections/src/templates/fixit/ by
-- `pnpm --filter @workspace/store-sections template:sql fixit 0095_library_templates_39_48_101_110.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'fixit',
    '{"ar":"فيكس إت","en":"Fixit"}'::jsonb,
    '{"ar":"صيانة موبايل وإكسسوارات: خدمات الصيانة ورحلتها، أسعار حسب الماركة، مقارنة سماعتين، باقات حماية، أدلة شراء والدعم. أربع صفحات جاهزة.","en":"Phone repair and accessories: repair services and journey, prices by brand, two earbuds compared, protection plans, buying guides and support. Four ready pages."}'::jsonb,
    'mobile-accessories',
    390,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
