--
-- Storefront template "Sufra" v1, generated from
-- packages/store-sections/src/templates/sufra/ by
-- `pnpm --filter @workspace/store-sections template:sql sufra 0095_library_templates_39_48_101_110.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'sufra',
    '{"ar":"سفرة","en":"Sufra"}'::jsonb,
    '{"ar":"أدوات سفرة بتركيز على التوصيل والدفع: يوصل بكره، موسم العزايم، طقم الجمعة، حسب ميزانيتك، طرق الدفع، افتح قبل ما تدفع وطقم المطبخ. أربع صفحات جاهزة.","en":"Tableware led by delivery and payment: tomorrow delivery, feast season, the Friday set, shop by budget, ways to pay, open before you pay and a kitchen kit. Four ready pages."}'::jsonb,
    'kitchen',
    410,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
