--
-- Storefront template "Sabaho" v1, generated from
-- packages/store-sections/src/templates/sabaho/ by
-- `pnpm --filter @workspace/store-sections template:sql sabaho 0095_library_templates_39_48_101_110.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'sabaho',
    '{"ar":"صباحو","en":"Sabaho"}'::jsonb,
    '{"ar":"توصيل فطار وبقالة: هدف التوصيل المجاني، فطار الويك إند، الأكتر إعادة طلب، البوكس الأسبوعي، مناطق ومواعيد التوصيل، كوبون أول طلب وتتبع الطلب. أربع صفحات جاهزة.","en":"Breakfast and pantry delivery: free delivery goal, the weekend breakfast, most reordered, the weekly box, delivery areas and cut-offs, a first-order coupon and order tracking. Four ready pages."}'::jsonb,
    'food',
    420,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
