), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'dar',
    '{"ar":"دار","en":"Dar"}'::jsonb,
    '{"ar":"بيت أثاث عائلي: من ١٩٨٢، الأكتر طلبًا، حاسبة التقسيط، زيارة مصمم، قصتنا ورحلتنا، بنشتغل إزاي والمعارض. أربع صفحات جاهزة.","en":"Family furniture house: since 1982, most ordered, installment calculator, designer home visit, our story and journey, how we work and showrooms. Four ready pages."}'::jsonb,
    'home',
    430,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
