-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'shabka',
    '{"ar":"شبكة","en":"Shabka"}'::jsonb,
    '{"ar":"دهب الشبكة والفرح: قياس خاص، هدايا حسب الشخص، الأكتر اختياراً، حجز قياس، كلمة الصايغة، كارت هدية، المحلات والأسئلة. أربع صفحات جاهزة.","en":"Bridal and engagement gold: private fittings, gifts by person, most chosen, a fitting booking, the goldsmith''s note, a gift card, the shops and questions. Four ready pages."}'::jsonb,
    'jewelry',
    440,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
