WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'hadaya',
    '{"ar":"هدايا","en":"Hadaya"}'::jsonb,
    '{"ar":"محل هدايا أطفال: الهدية الصح في دقيقتين، حسب السن، حسب الميزانية، باكدج الحفلة، كوبون وآراء الأهالي. أربع صفحات جاهزة.","en":"Kids’ gift shop: the right gift in two minutes, by age, by budget, a party pack, a coupon and parents’ reviews. Four ready pages."}'::jsonb,
    'kids',
    450,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
