-- 0095_library_templates_39_48_101_110.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Rep" v1, generated from
-- packages/store-sections/src/templates/rep/ by
-- `pnpm --filter @workspace/store-sections template:sql rep 0095_library_templates_39_48_101_110.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'rep',
    '{"ar":"ريب","en":"Rep"}'::jsonb,
    '{"ar":"نادي تمرين البيت: حسب الهدف، باكدج البداية، أطقم للصحاب، الكوتشات، الأرقام، اتمرن مع صاحبك ورسايل الأعضاء. أربع صفحات جاهزة.","en":"Home training club: shop by goal, a starter kit, sets for friends, the coaches, the numbers, train with a friend and members’ messages. Four ready pages."}'::jsonb,
    'sports',
    460,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
INSERT INTO template_versions (id, template_id, version, schema_version, config, changelog)
