    ids.template_id,
    'ghorza',
    '{"ar":"غُرزة","en":"Ghorza"}'::jsonb,
    '{"ar":"لبس جاهز وستوديو ترزية: الجديد، لوك العيد، أسعار التظبيط، حجز قياس، الترزية، وعودنا وكارت هدية. أربع صفحات جاهزة.","en":"Ready-to-wear with a tailoring studio: new in, an Eid look, alteration prices, a fitting booking, the tailors, our promises and a gift card. Four ready pages."}'::jsonb,
    'fashion',
    480,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
