WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'beity',
    '{"ar":"بيتي","en":"Beity"}'::jsonb,
    '{"ar":"متجر البيت والمطبخ: بانرات متحركة، الأقسام، رف الأسبوع، على قد الميزانية، عروض الأسبوع وافتح قبل ما تدفع. أربع صفحات جاهزة.","en":"Home and kitchen store: a banner carousel, departments, this week''s shelf, a budget shelf, the week''s offers and open before you pay. Four ready pages."}'::jsonb,
    'kitchen',
    1040,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
