-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'souq',
    '{"ar":"سوق","en":"Souq"}'::jsonb,
    '{"ar":"سوبر ماركت أونلاين: هدف التوصيل المجاني، بانرات متحركة، الأقسام، رف النهارده، مناطق الـ٤٥ دقيقة، طرق الدفع والدعم. أربع صفحات جاهزة.","en":"Online supermarket: free-delivery goal, a banner carousel, aisles, today''s shelf, 45-minute zones, ways to pay and support. Four ready pages."}'::jsonb,
    'food',
    1050,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
