-- 0095_library_templates_39_48_101_110.sql (storefront templates, 2026-10-19)
--
-- Storefront template "Salon" v1, generated from
-- packages/store-sections/src/templates/salon/ by
-- `pnpm --filter @workspace/store-sections template:sql salon 0095_library_templates_39_48_101_110.sql`.
-- Insert-only: Adds the template row (never
-- the default; the store keeps its own until the seller uses it) and its
-- version, only when the key is new.
-- An existing template (and its current version) is never changed.
--
-- Idempotent.

WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'salon',
    '{"ar":"صالون","en":"Salon"}'::jsonb,
    '{"ar":"أثاث الصالة: بانرات متحركة، الأوض، الأكثر مبيعاً، التقسيط لحد ٢٤ شهر ومواعيد التوصيل. أربع صفحات جاهزة.","en":"Living room furniture: banner carousel, rooms, best sellers, pay over 24 months and delivery times. Four ready pages."}'::jsonb,
    'home',
    1060,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
