WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'farha',
    '{"ar":"فرحة","en":"Farha"}'::jsonb,
    '{"ar":"محل ألعاب: بانرات متحركة، اختار حسب السن، أحسن الأطقم، باكدج البداية، آمن للعب وآراء الأهالي. أربع صفحات جاهزة.","en":"Toy store: banner carousel, shop by age, top kits, a starter pack, safe to play and parents’ reviews. Four ready pages."}'::jsonb,
    'kids',
    1080,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
