WITH ids AS (
  SELECT gen_random_uuid() AS template_id, gen_random_uuid() AS version_id
), new_template AS (
  INSERT INTO templates (id, key, name, description, category, sort_order, is_default, is_active, is_premium, current_version_id)
  SELECT
    ids.template_id,
    'nashat',
    '{"ar":"نشاط","en":"Nashat"}'::jsonb,
    '{"ar":"لياقة في البيت: بانرات متحركة، الأكثر مبيعاً، كل ما تزود توفّر ورسايل الكباتن. أربع صفحات جاهزة.","en":"Home fitness: banner carousel, best sellers, spend more save more and messages from captains. Four ready pages."}'::jsonb,
    'sports',
    1090,
    false,
    true,
    false,
    ids.version_id
  FROM ids
  ON CONFLICT (key) DO NOTHING
  RETURNING id, current_version_id
)
